$ErrorActionPreference='Stop';. "$PSScriptRoot/../ConnectivityDiagnostics.ps1"
$s=New-State test;Update-State $s $true (Get-Date) 5 $null|Out-Null;if($s.Status-ne'Online'-or$s.Successes-ne 1){throw 'success state failed'};Update-State $s $false (Get-Date) $null 'token=secret'|Out-Null;if($s.Status-ne'Offline'-or$s.Failures-ne 1){throw 'failure state failed'};$c=Get-Content "$PSScriptRoot/../config.json"-Raw|ConvertFrom-Json;if($c.publicTarget-ne'1.1.1.1'-or$c.internalTarget-ne'172.83.90.32'){throw 'targets failed'};$r=New-Report $c $s $s '203.0.113.1';if($r-match'secret'){throw 'redaction failed'};Write-Host 'All tests passed'
